class MockPlugin(ScannerPlugin):
    """Configurable mock plugin for deterministic testing."""

    def __init__(self, config: Dict[str, Any]):
        super().__init__(config)
        self.plugin_id = config.get("plugin_id", "mock_plugin")
        self.delay = config.get("delay", 0.0)
        self.raise_error = config.get("raise_error", False)
        self.findings_to_return = config.get("findings", [])
        self.execution_count = 0
        self.active_tasks = 0
        self.max_concurrent_observed = 0

    async def run(self, target: str) -> List[Finding]:
        """Simulate plugin execution with configurable behavior."""
        self.execution_count += 1
        self.active_tasks += 1
        self.max_concurrent_observed = max(self.max_concurrent_observed, self.active_tasks)
        
        try:
            if self.delay > 0:
                await asyncio.sleep(self.delay)
            
            if self.raise_error:
                raise RuntimeError(f"Plugin {self.plugin_id} simulated failure")
            
            return self.findings_to_return
        finally:
            self.active_tasks -= 1


def create_finding(
    plugin_id: str,
    severity: str = "medium",
    title: str = "Test Finding",
    target: str = "example.com"
) -> Finding:
    """Factory helper for Finding objects."""
    return Finding(
        plugin_id=plugin_id,
        severity=severity,
        title=title,
        target=target,
        description=f"Finding from {plugin_id} on {target}",
        remediation="Test remediation",
        cvss_score=5.0 if severity == "medium" else 9.0
    )


