class TestAsyncExecution:
    """Validate async task lifecycle and cancellation safety."""

    @pytest.mark.asyncio
    async def test_all_tasks_complete(self):
        """All plugin tasks should complete before scan returns."""
        engine = ScanEngine(max_concurrency=5)
        completed = []
        
        class CompletionPlugin(MockPlugin):
            async def run(self, target):
                await super().run(target)
                completed.append(self.plugin_id)
        
        for i in range(5):
            engine.register_plugin(CompletionPlugin({
                "plugin_id": f"plugin_{i}",
                "delay": 0.05
            }))
        
        await engine.scan("example.com")
        
        assert len(completed) == 5
        assert set(completed) == {f"plugin_{i}" for i in range(5)}

    @pytest.mark.asyncio
    async def test_cancellation_safety(self):
        """Scan should handle cancellation gracefully."""
        engine = ScanEngine(max_concurrency=5)
        
        for i in range(5):
            engine.register_plugin(MockPlugin({
                "plugin_id": f"plugin_{i}",
                "delay": 1.0  # Long delay
            }))
        
        task = asyncio.create_task(engine.scan("example.com"))
        await asyncio.sleep(0.1)
        task.cancel()
        
        with pytest.raises(asyncio.CancelledError):
            await task

    @pytest.mark.asyncio
    async def test_scan_timeout(self):
        """Scan should respect timeout configuration."""
        engine = ScanEngine(max_concurrency=5, timeout=0.5)
        
        engine.register_plugin(MockPlugin({
            "plugin_id": "slow_plugin",
            "delay": 2.0
        }))
        
        start = time.monotonic()
        results = await engine.scan("example.com")
        elapsed = time.monotonic() - start
        
        assert elapsed < 1.0  # Should timeout before 2s delay completes
        assert results == []  # No results from timed-out plugin

    @pytest.mark.asyncio
    async def test_sequential_scans(self):
        """Engine should support multiple sequential scans."""
        engine = ScanEngine(max_concurrency=5)
        engine.register_plugin(MockPlugin({
            "plugin_id": "plugin_a",
            "findings": [create_finding("plugin_a")]
        }))
        
        results1 = await engine.scan("target1.com")
        results2 = await engine.scan("target2.com")
        
        assert len(results1) == 1
        assert len(results2) == 1
        assert results1[0].target == "target1.com"
        assert results2[0].target == "target2.com"


